SCORING_SECTION = '''### **4.10.5 Session 2 Scoring and Missing-Output Accounting** {#4.10.5-session-2-scoring-and-missing-output-accounting}

For the 30 selected clips, let V be the number rated Valid, I the number rated Not valid, U the number rated No coaching feedback to assess, and M the number left unanswered. The accounting identity is V + I + U + M = 30. The primary full-set validity percentage is 100 × V / 30. A secondary assessed-output percentage is 100 × V / (V + I), reported only with its denominator and left unavailable when no output is assessed. U and M are reported separately and neither is treated as Valid. A final primary result is not declared until all 30 responses have been accounted for as submitted judgments; incomplete imports retain a provisional observed V/30 and an explicit missing count.

Coaching coverage is computed separately from coach ratings using the frozen system statuses. Corrective and positive messages count as substantive coaching, whereas low-confidence and unsupported partial messages do not. A displayed serve classification by itself does not qualify as coaching. The third response option evaluates absence of assessable coaching; it is not a separate assessment of whether abstaining was appropriate.

The scoring script matches C001–C030 by question header or clip ID, preserves the source export, and rejects unknown values or duplicate identifiers. Multiple response submissions require explicit selection rather than pooling. A Valid/Not valid rating on a notice-only output or a no-coaching rating on a substantive output is flagged for documented interpretation; the original answer is never automatically changed. No Session 2 pass threshold, independent subtype accuracy, binary whole-form accuracy or inter-rater statistic is introduced by this analysis.

'''


def main():
    global SOURCE
    manifest_path = DEST / 'revision_manifest.json'
    if manifest_path.exists() and json.loads(manifest_path.read_text(encoding='utf-8')).get('consistency_pass'):
        raise SystemExit('The manuscript has a later consistency revision. Do not overwrite it with the initial builder.')
    if not SOURCE.exists():
        SOURCE = DEST / 'source/Pascua-Leones_Thesis_2026-10-10.md'
    raw = SOURCE.read_bytes()
    if hashlib.sha256(raw).hexdigest() != EXPECTED_SHA:
        raise ValueError('Source manuscript changed; review replacements before rebuilding')
    original = raw.decode('utf-8-sig')
    lines = original.splitlines()
    assert lines[451] == '# **CHAPTER 4** {#chapter-4}'
    assert lines[947] == '# **BIBLIOGRAPHY** {#bibliography}'
    assert all(452 <= n < 948 for n in REPLACEMENTS)
    chapter4 = '\n'.join(REPLACEMENTS.get(i+1, lines[i]) for i in range(451, 947)) + '\n\n' + SCORING_SECTION
    chapters56 = (DEST / 'CHAPTERS_5_6.md').read_text(encoding='utf-8')
    normalized = original.replace('\r\n', '\n')
    before = normalized[:normalized.index('# **CHAPTER 4** {#chapter-4}')].rstrip('\n')
    toc_marker = '[**BIBLIOGRAPHY\t87**](#bibliography)'
    assert before.count(toc_marker) == 1
    toc_add = '[4.10.5 Session 2 Scoring and Missing-Output Accounting](#4.10.5-session-2-scoring-and-missing-output-accounting)\n\n[**CHAPTER 5 RESULTS AND DISCUSSION**](#chapter-5)\n\n[**CHAPTER 6 SUMMARY, CONCLUSIONS, AND RECOMMENDATIONS**](#chapter-6)\n\n'
    before = before.replace(toc_marker, toc_add + toc_marker)
    after = normalized[normalized.index('# **BIBLIOGRAPHY** {#bibliography}'):].rstrip('\n')
    text = before + '\n' + chapter4 + chapters56 + '\n\n' + after + '\n'
    source_copy = DEST / 'source/Pascua-Leones_Thesis_2026-10-10.md'
    source_copy.parent.mkdir(parents=True, exist_ok=True)
    if source_copy.exists() and hashlib.sha256(source_copy.read_bytes()).hexdigest() != EXPECTED_SHA:
        raise ValueError('Preserved manuscript copy differs; do not overwrite')
    if SOURCE.resolve() != source_copy.resolve():
        shutil.copy2(SOURCE, source_copy)
    target = DEST / 'Pascua-Leones_Thesis_Current.md'
    target.write_text(text, encoding='utf-8')
    metadata = dict(source_filename=SOURCE.name, source_sha256=EXPECTED_SHA,
        source_preserved=source_copy.relative_to(ROOT).as_posix(), working_copy=target.relative_to(ROOT).as_posix(),
        working_copy_sha256=hashlib.sha256(target.read_bytes()).hexdigest(),
        replaced_source_lines=sorted(REPLACEMENTS), added_sections=['4.10.5', 'Chapter 5', 'Chapter 6'],
        chapters_1_to_3_preserved=True, bibliography_appendices_and_image_definitions_preserved=True,
        session2_results='pending', device_latency='pending', model_and_feedback_changed=False)
    (DEST / 'revision_manifest.json').write_text(json.dumps(metadata, indent=2), encoding='utf-8')
    assert SOURCE.read_bytes() == raw == source_copy.read_bytes()
    # Verify image payloads, references, historical correspondence and early chapters stay intact.
    assert text[text.index('# **BIBLIOGRAPHY** {#bibliography}'):] == after + '\n'
    early_start = '# **CHAPTER 1** {#chapter-1}'
    assert text[text.index(early_start):text.index('# **CHAPTER 4** {#chapter-4}')].rstrip() == normalized[normalized.index(early_start):normalized.index('# **CHAPTER 4** {#chapter-4}')].rstrip()
    print(f'Created {target}; {len(REPLACEMENTS)} source-line replacements; original preserved.')


if __name__ == '__main__':
    main()
